inline int64_t ToolMessageMeasure( const ToolMessage & value )
{
    TableIds ids;
    const int64_t body = ToolMessageMeasureBody( ids, value );
    if ( body < 0 || ids.overflow ) { return -1; }
    return 1 + body + TableIdsBytes( ids );
}

