// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
static_assert( __is_trivially_copyable( User ), "User must stay relocatable" );
static_assert( __is_standard_layout( User ), "User must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Script ), "Script must stay relocatable" );
static_assert( __is_standard_layout( Script ), "Script must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Selection ), "Selection must stay relocatable" );
static_assert( __is_standard_layout( Selection ), "Selection must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( InsertText ), "InsertText must stay relocatable" );
static_assert( __is_standard_layout( InsertText ), "InsertText must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( RemoveText ), "RemoveText must stay relocatable" );
static_assert( __is_standard_layout( RemoveText ), "RemoveText must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Edit ), "Edit must stay relocatable" );
static_assert( __is_standard_layout( Edit ), "Edit must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( OpenDocument ), "OpenDocument must stay relocatable" );
static_assert( __is_standard_layout( OpenDocument ), "OpenDocument must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( SaveDocument ), "SaveDocument must stay relocatable" );
static_assert( __is_standard_layout( SaveDocument ), "SaveDocument must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Transaction ), "Transaction must stay relocatable" );
